/* رسوم مرئية للإجراءات التعليمية، بنفس الهوية الفنية للرسوم السابقة. */
(()=>{'use strict';
 const V=window.AL101_VISUALS, old=V.diagram;
 let serial=0;
 const templates={"102": {"kind": "argue", "labels": ["سؤال", "بحث وبيانات", "حجة علمية", "مراجعة"]}, "103": {"kind": "vote", "labels": ["تصويت أول", "حوار الأقران", "تصويت ثانٍ", "تبرير"]}, "104": {"kind": "flow", "labels": ["استجابة قبلية", "تشخيص", "تعديل الدرس", "تطبيق"]}, "105": {"kind": "fade", "labels": ["مثال كامل", "إخفاء خطوة", "مساندة أقل", "حل مستقل"]}, "106": {"kind": "timeline", "labels": ["اليوم ١", "بعد أيام", "بعد أسبوع", "مراجعة"]}, "107": {"kind": "compare", "labels": ["حالة أ", "حالة ب", "قارن", "قاعدة"]}, "108": {"kind": "cycle", "labels": ["نموذج أولي", "دليل", "تحسين", "نموذج منقح"]}, "109": {"kind": "explain", "labels": ["حلّ خطوة", "لماذا؟", "ربط المبدأ", "تحقق"]}, "110": {"kind": "cycle", "labels": ["خطّط", "نفّذ", "راقب", "قيّم"]}, "111": {"kind": "design", "labels": ["تحدٍّ", "قيود", "نموذج أولي", "اختبار"]}, "112": {"kind": "predict", "labels": ["تنبّأ", "لاحظ", "فسّر", "راجع"]}, "113": {"kind": "problem", "labels": ["مشكلة", "أسئلة بحث", "حلول", "تبرير"]}, "114": {"kind": "team", "labels": ["اختبار فردي", "اختبار فريق", "تغذية راجعة", "تطبيق"]}, "115": {"kind": "questions", "labels": ["أسئلة كثيرة", "تصنيف", "تحسين", "أولوية"]}, "116": {"kind": "flipped", "labels": ["تعلّم قبلي", "نشاط صفي", "توجيه", "تطبيق"]}, "117": {"kind": "interleave", "labels": ["أ", "ب", "ج", "أ / ج / ب"]}, "118": {"kind": "vote", "labels": ["تقويم فردي", "نقاش فريق", "تصحيح", "تأمل"]}, "119": {"kind": "debate", "labels": ["موقف أ", "موقف ب", "تبادل الأدوار", "رأي مركّب"]}, "120": {"kind": "mastery", "labels": ["تعلم", "تقويم", "دعم علاجي", "إتقان"]}, "121": {"kind": "knowledge", "labels": ["أفكار", "أدلة", "تحسين", "معرفة مشتركة"]}, "122": {"kind": "refute", "labels": ["تصور شائع", "دليل مضاد", "تفسير علمي", "تطبيق"]}};
 const esc=V.esc;
 const short=(s,n=14)=>String(s||'').length>n?String(s||'').slice(0,n-1)+'…':String(s||'');
 const el=(x,y,w,h,c,pale,text,fill='#fff')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="13" fill="${fill}" stroke="${c}" stroke-width="1.8"/><text x="${x+w/2}" y="${y+h/2+5}" font-size="15" font-weight="700" fill="#244b5c" text-anchor="middle" direction="rtl" unicode-bidi="plaintext" font-family="Noto Sans Arabic,Arial">${esc(short(text,14))}</text>`;
 const line=(x1,y1,x2,y2,c,dashed=false)=>`<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${c}" stroke-width="3" stroke-linecap="round" ${dashed?'stroke-dasharray="6 6"':''}/>`;
 const arrow=(x1,y1,x2,y2,c)=>`${line(x1,y1,x2,y2,c)}<path d="M${x2-8} ${y2-7} L${x2} ${y2} L${x2-8} ${y2+7}" fill="none" stroke="${c}" stroke-width="3" stroke-linecap="round"/>`;
 const circle=(x,y,r,c,pale,s)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${pale}" stroke="${c}" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-weight="800" font-size="15" fill="${c}">${esc(String(s))}</text>`;
 function middle(t,c,pale){const a=t.labels;
  switch(t.kind){
   case 'vote':return `${el(44,81,115,81,c,pale,a[0],pale)}${arrow(164,121,210,121,c)}${circle(272,120,43,c,pale,'↔')}${arrow(316,121,362,121,c)}${el(372,81,160,81,c,pale,a[2])}<text x="288" y="190" text-anchor="middle" font-size="15" font-weight="700" fill="${c}">${esc(a[1])}</text>`;
   case 'cycle':return `${el(190,48,180,52,c,pale,a[0],pale)}${el(382,115,154,62,c,pale,a[1])}${el(190,174,180,48,c,pale,a[2],pale)}${el(44,115,135,62,c,pale,a[3])}${arrow(375,89,436,111,c)}${arrow(386,175,366,190,c)}${arrow(180,193,151,176,c)}${arrow(154,113,204,85,c)}`;
   case 'compare':return `${el(55,66,194,78,c,pale,a[0])}${el(327,66,194,78,c,pale,a[1])}${line(150,145,222,173,c)}${line(428,145,356,173,c)}${el(212,173,160,47,c,pale,a[2],pale)}<text x="287" y="158" font-size="16" font-weight="800" fill="${c}" text-anchor="middle">⇩</text>`;
   case 'timeline':return `${line(55,139,524,139,c)}${a.map((x,i)=>`${circle(88+i*147,139,26,c,i%2?pale:'#fff',i+1)}<text x="${88+i*147}" y="${90+(i%2)*7}" text-anchor="middle" font-size="15" fill="${c}" font-weight="700">${esc(short(x,12))}</text>`).join('')}`;
   case 'fade':return `${a.map((x,i)=>`${el(40+i*137,70+i*19,120,100-i*18,c,pale,x,i%2?pale:'#fff')}`).join('')}`;
   case 'argue':return `${circle(101,119,42,c,pale,'؟')}${arrow(145,118,174,118,c)}${el(183,68,164,100,c,pale,a[1])}${arrow(355,118,395,118,c)}${circle(464,119,50,c,pale,'دليل')}<text x="290" y="199" font-size="17" fill="${c}" font-weight="700" text-anchor="middle">حجة ← مراجعة ← تحسين</text>`;
   case 'design':case 'problem':return `${el(42,78,150,90,c,pale,a[0])}${arrow(195,126,244,126,c)}<path d="M246,80 L338,80 L361,126 L338,172 L246,172 L224,126Z" fill="${pale}" stroke="${c}" stroke-width="2"/><text x="291" y="130" font-size="14" font-weight="700" fill="${c}" text-anchor="middle">${esc(a[1])}</text>${arrow(362,126,399,126,c)}${el(405,78,135,90,c,pale,a[3])}`;
   case 'team':return `${el(62,67,125,73,c,pale,a[0])}${el(228,67,125,73,c,pale,a[1],pale)}${el(394,67,125,73,c,pale,a[2])}${arrow(190,101,224,101,c)}${arrow(356,101,390,101,c)}${el(215,174,154,42,c,pale,a[3],pale)}`;
   case 'debate':return `${el(50,68,184,80,c,pale,a[0])}${el(346,68,184,80,c,pale,a[1])}${arrow(238,110,342,110,c)}${arrow(342,140,238,140,c)}${el(209,174,170,44,c,pale,a[3],pale)}`;
   case 'knowledge':return `${el(54,81,147,91,c,pale,a[0])}${el(230,81,147,91,c,pale,a[1],pale)}${el(406,81,136,91,c,pale,a[3])}${arrow(202,127,227,127,c)}${arrow(378,127,404,127,c)}`;
   case 'mastery':return `${el(45,75,144,88,c,pale,a[0])}${el(222,75,144,88,c,pale,a[1],pale)}${el(402,75,132,88,c,pale,a[3])}${arrow(190,119,219,119,c)}${arrow(367,119,399,119,c)}<text x="289" y="194" font-size="16" text-anchor="middle" fill="${c}" font-weight="800">↺ ${esc(a[2])}</text>`;
   case 'interleave':return `${[0,1,2,0,2,1].map((v,i)=>`${circle(83+i*82,123,26,c,i%2?pale:'#fff',a[v])}${i<5?arrow(113+i*82,123,134+i*82,123,c):''}`).join('')}`;
   case 'refute':return `${el(45,66,155,86,c,pale,a[0])}${arrow(205,109,238,109,c)}${circle(284,110,43,c,pale,'!')}${arrow(330,109,366,109,c)}${el(370,66,169,86,c,pale,a[2],pale)}<text x="286" y="196" text-anchor="middle" fill="${c}" font-size="15">${esc(a[1])}</text>`;
   default:return `${a.map((x,i)=>`${el(23+i*139,92,124,78,c,pale,x,i%2?pale:'#fff')}${i<3?arrow(148+i*139,132,160+i*139,132,c):''}`).join('')}`;
  }
 }
 V.diagram=(s,options={})=>{
  const t=templates[s.id];if(!t)return old(s,options);
  const palette=V.category(s),c=palette.color,pale=palette.light, uid=`custom${s.id}-${++serial}`;
  const steps=s.steps.slice(0,4);
  const foot=steps.map(([title],i)=>`<rect x="${18+i*139}" y="233" width="132" height="35" rx="11" fill="${i===0?pale:'#fff'}" stroke="#d6e2e9"/><text x="${84+i*139}" y="255" text-anchor="middle" fill="#244b5c" font-family="Noto Sans Arabic,Arial" font-size="12" font-weight="700" direction="rtl" unicode-bidi="plaintext">${i+1}. ${esc(short(title,10))}</text>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 580 278" class="strategy-diagram" role="img" aria-label="رسم يوضح ترتيب العمل في استراتيجية ${esc(s.name)}"><defs><pattern id="dots-${uid}" x="0" y="0" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#d6e2e9"/></pattern></defs><rect x="1" y="1" width="578" height="276" rx="22" fill="#fbfdff" stroke="#d6e2e9"/><rect x="1" y="1" width="578" height="276" rx="22" fill="url(#dots-${uid})" opacity=".36"/><path d="M0 0 L116 0 L0 116 Z" fill="${pale}" opacity=".65"/><rect x="15" y="11" width="174" height="28" rx="14" fill="${pale}" stroke="${c}"/><text x="102" y="31" direction="rtl" unicode-bidi="plaintext" font-family="Noto Sans Arabic,Arial" font-size="12" font-weight="700" fill="${c}" text-anchor="middle">${esc(palette.label)}</text>${middle(t,c,pale)}${foot}</svg>`;
 };
})();
